<!-- WARNING: 本项目专属“粘人精”，严禁出现 Kiro、Krio、周棋洛等任何相关英文或拼音命名！ -->
<script setup lang="ts">
import { computed, ref } from 'vue'
import { GROUP_FINANCE_FEATURES, type GroupFinanceCategory } from '../../../services/groupFinance'
const props = defineProps<{ visible: boolean; group: any }>()
const emit = defineEmits<{ (e: 'close'): void; (e: 'save'): void }>()
const tab = ref<'features' | 'ledger'>('features')
const categories: Array<{ id: GroupFinanceCategory; label: string }> = [{ id: 'packet', label: '红包玩法' }, { id: 'transfer', label: '转账功能' }, { id: 'collection', label: '群收款' }]
const enabledCount = computed(() => Object.values(props.group.groupFinanceSettings?.features || {}).filter(Boolean).length)
const toggleFeature = (id: string) => { props.group.groupFinanceSettings.features[id] = !props.group.groupFinanceSettings.features[id]; emit('save') }
const setAll = (value: boolean) => { for (const item of GROUP_FINANCE_FEATURES) props.group.groupFinanceSettings.features[item.id] = value; emit('save') }
const name = (id: string) => id === 'system'
  ? '系统'
  : id === 'user'
    ? (props.group.userProfile?.name || '我')
    : props.group.memberNicknames?.[id] || props.group.memoryMemberNames?.[id] || props.group.removedMembers?.[id]?.name || '群成员'
const money = (cents: number) => `${cents >= 0 ? '' : '-'}¥${(Math.abs(cents) / 100).toFixed(2)}`
</script>
<template>
  <Teleport to="body"><div v-if="visible" class="gfs-overlay" @click.self="emit('close')"><section class="gfs-sheet"><header><div><b>群资金互动</b><small>{{ group.name }}</small></div><button type="button" @click="emit('close')">×</button></header>
    <nav><button type="button" :class="{ active: tab === 'features' }" @click="tab = 'features'">功能</button><button type="button" :class="{ active: tab === 'ledger' }" @click="tab = 'ledger'">群账本</button></nav>
    <main v-if="tab === 'features'">
      <div class="gfs-master"><div><b>群红包与资金互动</b><small>关闭后用户入口与 AI 相关提示模块同时移除</small></div><label class="switch"><input v-model="group.groupFinanceSettings.enabled" type="checkbox" @change="emit('save')"><span></span></label></div>
      <template v-if="group.groupFinanceSettings.enabled"><div class="gfs-tools"><span>已开启 {{ enabledCount }}/{{ GROUP_FINANCE_FEATURES.length }}</span><button type="button" @click="setAll(true)">全部开启</button><button type="button" @click="setAll(false)">全部关闭</button></div>
      <section v-for="category in categories" :key="category.id"><h3>{{ category.label }}</h3><button v-for="item in GROUP_FINANCE_FEATURES.filter(feature => feature.category === category.id)" :key="item.id" type="button" class="gfs-row" @click="toggleFeature(item.id)"><span>{{ item.label }}</span><i :class="{ active: group.groupFinanceSettings.features[item.id] }">✓</i></button></section>
      <p class="gfs-note">每个开关同时控制用户入口、AI 主动发起与参与说明、输出解析和程序执行。开启的玩法会以完整独立模块加入同一次群聊请求，不增加模型调用次数。</p></template>
    </main>
    <main v-else><div class="gfs-master"><div><b>自动记录群资金流水</b><small>关闭只停止新增账本记录，不删除现有记录</small></div><label class="switch"><input v-model="group.groupFinanceSettings.ledgerEnabled" type="checkbox" @change="emit('save')"><span></span></label></div><div v-if="group.groupFinanceState?.ledger?.length" class="gfs-ledger"><div v-for="item in group.groupFinanceState.ledger" :key="item.id"><span><b>{{ item.note || '群资金互动' }}</b><small>{{ name(item.actorId) }} · {{ new Date(item.createdAt).toLocaleString('zh-CN') }}</small></span><em>{{ money(item.amountCents) }}</em></div></div><div v-else class="gfs-empty">暂无群资金记录</div></main>
  </section></div></Teleport>
</template>
<style scoped>
